package server

import (
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"yozakura/backend/pkg/brand"
)

func writeFile(t *testing.T, path, text string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(text), 0o644); err != nil {
		t.Fatal(err)
	}
}

// Only keys the user sets after the generated file is sourced (through
// our entry overlay, whose own appearance block does not count) override.
func TestUserOverridesAfterGeneratedSource(t *testing.T) {
	dir := t.TempDir()
	gen := filepath.Join(dir, "data", "hyprland.yozd.conf")
	entry := filepath.Join(dir, "data", "hyprland.conf")
	root := filepath.Join(dir, "hypr", "hyprland.conf")
	writeFile(t, gen, "general {\n    gaps_in = 5\n}\n")
	writeFile(t, entry, "# Generated by "+brand.DisplayName+" - do not edit\nsource = "+gen+"\ngeneral {\n    gaps_out = 9\n}\n")
	writeFile(t, filepath.Join(dir, "hypr", "extra", "a.conf"), "decoration {\n    rounding = 4\n}\n")
	writeFile(t, root, "general:border_size = 2\n"+
		"source = "+entry+"\n"+
		"# general:gaps_in = 1\n"+
		"$mod = SUPER\n"+
		"general {\n    gaps_in = 3\n    col.active_border = rgb(ffffff)\n}\n"+
		"source = extra/*.conf\n"+
		"source = "+root+"\n") // a cycle is ignored
	got := userOverrides(root, gen)
	want := map[string]bool{"general:gaps_in": true, "general:col.active_border": true, "decoration:rounding": true}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("overrides = %v, want %v", got, want)
	}
	if len(userOverrides(filepath.Join(dir, "missing.conf"), gen)) != 0 {
		t.Fatal("a missing config overrides nothing")
	}
}

// A key the user sets again after the generated file is not pushed live
// (it would beat their value until the next reload): Hyprland reloads.
func TestHyprlandUserOverrideReloadsInsteadOfKeyword(t *testing.T) {
	h, f, conf := hyprHandler(t, false)
	writeFile(t, hyprUserConfig(), "source = "+conf+"\ngeneral {\n    gaps_in = 1\n}\n")
	_ = h.ApplyConfig(hyprPayload(5))
	if err := h.ApplyConfig(hyprPayload(6)); err != nil {
		t.Fatal(err)
	}
	if f.reloads != 2 || len(f.batches) != 0 {
		t.Fatalf("overridden key: reloads=%d batches=%q", f.reloads, f.batches)
	}
}

// A rejected keyword falls back to a reload; when that fails too, the
// next apply reloads instead of diffing against values never applied.
func TestHyprlandRejectedKeywordReloads(t *testing.T) {
	h, f, _ := hyprHandler(t, false)
	_ = h.ApplyConfig(hyprPayload(5))
	f.batchErr = errors.New("hyprland rejected")
	if err := h.ApplyConfig(hyprPayload(6)); err != nil {
		t.Fatal(err)
	}
	if f.reloads != 2 || len(f.batches) != 1 {
		t.Fatalf("rejected keyword: reloads=%d batches=%q", f.reloads, f.batches)
	}
	f.reloadErr = errors.New("reload failed")
	if err := h.ApplyConfig(hyprPayload(7)); err == nil {
		t.Fatal("a failed fallback reload must be reported")
	}
	f.batchErr, f.reloadErr = nil, nil
	if err := h.ApplyConfig(hyprPayload(8)); err != nil {
		t.Fatal(err)
	}
	if f.reloads != 4 || len(f.batches) != 2 {
		t.Fatalf("after a failed reload: reloads=%d batches=%q, want a reload, no keyword", f.reloads, f.batches)
	}
}
